contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable {
        uint beforeBalance = address(c).balance;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        assert(beforeBalance >= amount && address(c).balance == beforeBalance - amount);
    }

    receive() external payable {}
}

